#nullable enable // autogenerated

using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Callbacks;
using MVZ2Logic.Grids;
using MVZ2Logic.Level;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Areas
{
    [AutoAreaDefinition(VanillaAreaNames.mountain)]
    public class Mountain : AreaDefinition
    {
        public Mountain(string nsp, string name) : base(nsp, name)
        {
            SetProperty(VanillaAreaProps.WATER_COLOR, new Color(0, 0.48f, 0.89f, 1));
            SetProperty(VanillaAreaProps.WATER_COLOR_CENSORED, new Color(0, 0.48f, 0.89f, 1));
            AddTrigger(LogicLevelCallbacks.IS_TERRAIN, IsWaterCallback, filter: LogicTerrainTypes.water);
        }
        public override void Setup(LevelEngine level)
        {
            base.Setup(level);
            level.Spawn(VanillaEffectID.miner, new Vector3(600, 0, 40), null);
            level.Spawn(VanillaEffectID.waterfall, new Vector3(100, 0, 120), null);
        }
        public override void Update(LevelEngine level)
        {
            base.Update(level);
            var wave = GetPoolWave(level);
            wave = (wave + 0.01f) % 1;
            SetPoolWave(level, wave);

            var model = level.GetAreaModelInterface();
            if (model != null)
            {
                model.SetModelProperty("WindSpeed", level.GetCurrentDecorativeWindSpeed());
            }
        }
        public override float GetGroundY(LevelEngine level, float x, float z)
        {
            var column = level.GetColumn(x);
            var lane = level.GetLane(z);
            var grid = level.GetGrid(column, lane);
            if (grid != null && grid.IsWater())
            {
                // 水中
                return -1 + Mathf.Sin(((x + z) * 0.01f + GetPoolWave(level)) * 4 * Mathf.PI);
            }
            return base.GetGroundY(level, x, z);
        }
        private void IsWaterCallback(LogicLevelCallbacks.IsTerrainCallbackParams args, CallbackResult result)
        {
            var level = args.level;
            if (level.AreaID != VanillaAreaID.mountain)
                return;
            var column = level.GetColumn(args.x);
            var lane = level.GetLane(args.z);
            if (lane >= 1 && lane <= 4 && (column <= 9 || column >= 13))
            {
                result.SetValue(true);
            }
        }
        public static float GetPoolWave(LevelEngine level)
        {
            return level.GetProperty<float>(PROP_POOL_WAVE);
        }
        public static void SetPoolWave(LevelEngine level, float value)
        {
            level.SetProperty(PROP_POOL_WAVE, value);
        }
        public static readonly VanillaLevelPropertyMeta<float> PROP_POOL_WAVE = new VanillaLevelPropertyMeta<float>("PoolWave");
    }
}